@push('scripts')<script>let count=0;const previous=Object.values(
@json(old('items',[])));function total(){let cents=0n;document.querySelectorAll('.sale-row').forEach(row=>{const amount=Vendra.lineCents(row.querySelector('.qty').value,row.querySelector('.price').value);if(amount!==null)cents+=amount;});document.querySelector('#total').textContent='Total: '+Vendra.centsText(cents);}function add(data){const row=document.querySelector('#row').content.firstElementChild.cloneNode(true);const idx=count++;['kind','item-id','qty','price'].forEach((c,i)=>row.querySelector('.'+c).name=`items[${idx}][${['kind','id','quantity','unit_price'][i]}]`);row.querySelector('.choice').onchange=e=>{const[k,id]=e.target.value.split(':');row.querySelector('.kind').value=k||'';row.querySelector('.item-id').value=id||'';row.querySelector('.price').value=e.target.selectedOptions[0].dataset.price||'';total();};row.querySelectorAll('input').forEach(e=>e.oninput=total);row.querySelector('.remove').onclick=()=>{row.remove();total();document.querySelector('#add').focus();};document.querySelector('#items').append(row);Vendra.associateLabels(row);if(data){row.querySelector('.choice').value=data.kind+':'+data.id;row.querySelector('.choice').dispatchEvent(new Event('change'));row.querySelector('.qty').value=data.quantity;row.querySelector('.price').value=data.unit_price;}total();}document.querySelector('#add').onclick=()=>add();if(previous.length)previous.forEach(add);else add();</script>
